import { ChangeDetectionStrategy, Component, input } from '@angular/core';
import { IconName } from '@models/icon-names.generated';

export type { IconName };

/**
 * A glyph of the icon font generated by fantasticon (`npm run generate-fonts`, sources in
 * src/assets/icons/src). Takes the text colour; `size` is in pixels.
 */
@Component({
  selector: 'app-icon',
  template: '<i class="icon__glyph" [class]="\'icon__glyph icon-\' + name()"></i>',
  styles: `
    :host {
      @apply inline-flex shrink-0 items-center justify-center leading-none;
      font-size: var(--icon-size);
      width: var(--icon-size);
      height: var(--icon-size);
    }
    .icon__glyph {
      @apply block leading-none;
    }
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { class: 'icon', 'aria-hidden': 'true', '[style.--icon-size.px]': 'size()' },
})
export class IconComponent {
  readonly name = input.required<IconName>();
  readonly size = input(20);
}
